/* The Radar screen (knowledge-base/features/ops-control-panel.md §6). Dark by default; light follows html[data-theme].
   The sweep is slow and smooth on purpose (60 s a turn). Typefaces are the console's own (../styles/tokens.css). */

.radar-screen {
  --radar-ink: #f8fafc;
  --radar-ink-2: #ffffff;
  --radar-muted: #cbd5e1;
  --radar-dim: #94a3b8;
  --radar-faint: #7b8ba3;
  --radar-accent: #2563eb;
  --radar-amber: #ffb547;
  --radar-amber-ink: #ffc46b;
  --radar-lime: #93c5fd;
  --radar-resolved: #60a5fa;
  --radar-line: rgba(59, 130, 246, 0.16);
  --radar-detail: #93c5fd;
  --radar-stale-ink: #ffd9a0;
  --radar-on-pressed: #eff6ff;
  --radar-pill-ack: #bfdbfe;
  --radar-ring-label: rgba(147, 197, 253, 0.75);
  /* Flat page ground — no full-screen gradient; the scope disc keeps its own fill. */
  --radar-ground: #0a0f1a;
  --radar-head-bg: #101828;
  --radar-panel-bg: #101828;
  --radar-panel-hover: #16233a;
  --radar-disc: radial-gradient(circle, rgba(30, 58, 138, 0.45) 0%, rgba(16, 24, 40, 0.75) 55%, rgba(10, 15, 26, 0.95) 100%);
  --radar-axis-bg: rgba(16, 24, 40, 0.92);
  --radar-telemetry-bg: #101828;
  --radar-crt: none;
  --radar-sweep-blend: screen;
  --radar-display: "IBM Plex Sans", system-ui, sans-serif;
  --radar-mono: "IBM Plex Mono", ui-monospace, Menlo, monospace;
  position: relative;
  flex-grow: 1;
  display: flex;
  flex-direction: column;
  min-height: 0;
  overflow: hidden;
  background: var(--radar-ground);
  color: var(--radar-ink);
  font-family: var(--radar-display);
  animation: none;
}
.radar-screen:fullscreen { overflow: auto; }
.radar-screen button { font-family: inherit; }
.radar-screen button:focus-visible, .radar-screen a:focus-visible { outline: 2px solid var(--radar-accent); outline-offset: 2px; }

/* The screen's own header — it stands alone in full screen. */
.radar-head { display: flex; align-items: center; gap: 20px; padding: 12px 32px; border-bottom: 1px solid var(--radar-line); background: var(--radar-head-bg); white-space: nowrap; }
.radar-head > * { flex-shrink: 0; }
.radar-head > .radar-head-gap { flex-shrink: 1; min-width: 0; }
/* the tenant's logo leads the header only in full screen, where the console's own header is gone */
.radar-head-logo { display: none; }
.radar-screen:fullscreen .radar-head-logo { display: flex; align-items: center; padding-right: 20px; border-right: 1px solid var(--radar-line); }
.radar-head-logo img { height: 30px; width: auto; max-width: 140px; object-fit: contain; }
.radar-head-gap { flex-grow: 1; }
/* The app header above already carries the airline's mark: the Radar's own shows only full screen, like the dCortex wordmark. */
.radar-head-tenant { display: none; height: 28px; width: 28px; border-radius: 8px; object-fit: cover; }
.radar-screen:fullscreen .radar-head-tenant { display: block; }
.radar-brand { display: flex; align-items: center; gap: 12px; line-height: 1.05; }
.radar-brand-title { font-family: var(--radar-mono); font-size: 13px; font-weight: 600; letter-spacing: 3px; color: var(--radar-muted); white-space: nowrap; }
.radar-brand-ring { fill: none; stroke: var(--radar-accent); stroke-width: 1.5; }
.radar-brand-ring--inner { stroke: rgba(59, 130, 246, 0.5); stroke-width: 1.2; }
.radar-brand-beam { stroke: var(--radar-accent); stroke-width: 2; }
.radar-brand-blip { fill: var(--radar-amber); }
.radar-feed-pill { display: flex; align-items: center; gap: 8px; padding: 6px 12px; border: 1px solid rgba(59, 130, 246, 0.3); border-radius: 999px; font-family: var(--radar-mono); font-size: 12px; letter-spacing: 1px; white-space: nowrap; }
.radar-feed-pill--stale { border-color: var(--radar-amber); color: var(--radar-stale-ink); }
.radar-feed-pill--stale .radar-live-dot { background: var(--radar-amber); box-shadow: 0 0 10px var(--radar-amber); }
.radar-live-dot { width: 8px; height: 8px; border-radius: 50%; background: var(--radar-accent); box-shadow: 0 0 10px var(--radar-accent); animation: radar-livedot 1.2s infinite; }
.radar-clock { display: flex; flex-direction: column; align-items: flex-end; line-height: 1.1; font-family: var(--radar-mono); }
.radar-clock-time { font-size: 20px; font-weight: 600; }
.radar-clock--utc .radar-clock-time { color: var(--radar-dim); }
.radar-clock-label { font-size: 10px; letter-spacing: 2px; color: var(--radar-dim); }
.radar-head-button { min-height: 36px; padding: 6px 12px; border: 1px solid rgba(59, 130, 246, 0.35); border-radius: 8px; background: transparent; color: var(--radar-muted); font-family: var(--radar-mono); font-size: 12px; font-weight: 600; letter-spacing: 1.5px; cursor: pointer; }
.radar-screen:fullscreen .radar-head-button { display: none; }
.radar-modes { display: inline-flex; align-items: stretch; margin-left: auto; border: 1px solid rgba(59, 130, 246, 0.3); border-radius: 8px; overflow: hidden; background: transparent; }
.radar-modes .radar-mode { min-height: 36px; padding: 6px 14px; border: 0; border-radius: 0; background: transparent; color: var(--radar-muted); font-family: var(--radar-mono); font-size: 12px; font-weight: 600; letter-spacing: 1.5px; line-height: 1.25; cursor: pointer; }
.radar-modes .radar-mode + .radar-mode { border-left: 1px solid rgba(59, 130, 246, 0.3); }
.radar-modes .radar-mode[aria-pressed="true"] { background: rgba(59, 130, 246, 0.14); color: var(--radar-ink); }
.radar-modes .radar-mode:focus-visible { outline: 2px solid var(--radar-accent); outline-offset: -2px; }
.radar-days { display: flex; align-items: center; gap: 6px; font-family: var(--radar-mono); font-size: 13px; letter-spacing: 1px; }
.radar-day-step { min-width: 36px; min-height: 36px; border: 1px solid rgba(59, 130, 246, 0.3); border-radius: 8px; background: transparent; color: var(--radar-muted); cursor: pointer; }
.radar-day-step:disabled { opacity: 0.35; cursor: default; }
.radar-day-label { min-width: 92px; text-align: center; font-weight: 600; color: var(--radar-ink); }
.radar-day-live { min-height: 36px; padding: 6px 12px; border: 1px solid var(--radar-accent); border-radius: 8px; background: rgba(59, 130, 246, 0.14); color: var(--radar-ink); font-family: var(--radar-mono); font-size: 12px; font-weight: 600; letter-spacing: 1.5px; cursor: pointer; }
.radar-feed-pill--replay { border-color: var(--radar-amber); background: rgba(255, 181, 71, 0.1); color: var(--radar-stale-ink); }
.radar-tenant { padding-left: 16px; border-left: 1px solid var(--radar-line); font-size: 13px; font-weight: 600; letter-spacing: 1px; color: var(--radar-muted); }
/* a narrower screen drops what it can read elsewhere: the tenant (console header), the subtitle, then the UTC clock */
@media (max-width: 1280px) { .radar-tenant { display: none; } }
@media (max-width: 1040px) { .radar-clock--utc { display: none; } .radar-head { gap: 14px; padding: 10px 16px; } }

.radar-main { flex-grow: 1; display: grid; grid-template-columns: minmax(340px, 470px) minmax(0, 1fr); gap: clamp(28px, 4vw, 72px); padding: 24px 32px 28px; min-height: 0; }
@media (max-width: 1040px) { .radar-main { grid-template-columns: minmax(0, 1fr); gap: 28px; padding: 18px 16px 20px; } }

/* The feed. */
.radar-feed { display: flex; flex-direction: column; gap: 16px; min-width: 0; }
.radar-feed-head { display: flex; align-items: flex-end; justify-content: space-between; gap: 12px; }
.radar-eyebrow { display: block; font-family: var(--radar-mono); font-size: 11px; letter-spacing: 3px; color: var(--radar-dim); }
.radar-feed-head h1 { margin: 4px 0 0; font-size: 24px; font-weight: 600; letter-spacing: 1px; }
.radar-shown { font-family: var(--radar-mono); font-size: 12px; color: var(--radar-dim); text-align: right; }
.radar-x { flex-shrink: 0; display: inline-flex; align-items: center; justify-content: center; width: 28px; height: 28px; padding: 0; border: 1px solid rgba(59, 130, 246, 0.3); border-radius: 50%; background: transparent; color: var(--radar-muted); font-size: 17px; line-height: 1; cursor: pointer; }
.radar-x:hover { border-color: var(--radar-accent); color: var(--radar-ink); background: rgba(59, 130, 246, 0.1); }
.radar-locked { position: relative; }
/* the filtered list's own header: what is shown, and the × that clears it */
.radar-filterbar { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin-bottom: -6px; padding: 6px 4px 6px 12px; border-radius: 8px; background: rgba(59, 130, 246, 0.06); }
.radar-locked-close { position: absolute; top: 12px; right: 12px; }
.radar-locked-meta { padding-right: 40px; }
.radar-no-match { margin: 16px 0; font-size: 13px; color: var(--radar-muted); }
.radar-link { padding: 0; border: 0; background: none; color: var(--radar-accent); font-size: inherit; text-decoration: underline; cursor: pointer; }

.radar-kpis { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 0; border: 1px solid var(--radar-line); border-radius: 10px; overflow: hidden; background: var(--radar-panel-bg); }
.radar-kpi { display: flex; flex-direction: column; align-items: flex-start; gap: 8px; padding: 14px 14px 12px; border: 0; border-radius: 0; border-top: 2px solid transparent; border-right: 1px solid var(--radar-line); background: var(--radar-panel-bg); color: inherit; text-align: left; cursor: pointer; }
.radar-kpi:last-child { border-right: 0; }
.radar-kpi:hover { background: var(--radar-panel-hover); }
.radar-kpi[aria-pressed="true"] { background: rgba(59, 130, 246, 0.12); border-top-color: var(--radar-accent); }
.radar-kpi-value { font-size: 26px; font-weight: 600; line-height: 1; font-variant-numeric: tabular-nums; }
.radar-kpi-label { min-height: 2.6em; font-family: var(--radar-mono); font-size: 11px; line-height: 1.35; letter-spacing: 1px; color: var(--radar-muted); }
.radar-kpi--action { border-top-color: rgba(255, 181, 71, 0.7); }
.radar-kpi--action .radar-kpi-value { color: var(--radar-amber-ink); }
.radar-kpi--action .radar-kpi-label { color: var(--radar-stale-ink); }
.radar-kpi--action[aria-pressed="true"] { background: rgba(255, 181, 71, 0.12); border-top-color: var(--radar-amber); }
.radar-kpi--new .radar-kpi-value { color: var(--radar-accent); }
.radar-kpi--resolved .radar-kpi-value { color: var(--radar-dim); }

/* an even grid: every chip whole, rows aligned, however many fit across */
.radar-chips { display: grid; grid-template-columns: repeat(auto-fill, minmax(130px, 1fr)); gap: 8px; }
.radar-chip { min-height: 32px; text-align: center; padding: 7px 14px; border-radius: 8px; border: 1px solid rgba(59, 130, 246, 0.22); background: transparent; color: var(--radar-muted); font-family: var(--radar-mono); font-size: 11px; font-weight: 600; letter-spacing: 1px; line-height: 1.25; white-space: nowrap; cursor: pointer; }
.radar-chip:hover { border-color: rgba(59, 130, 246, 0.4); }
.radar-screen .radar-chip, .radar-screen .radar-toolbar button { font-family: var(--radar-mono); }
.radar-chip--hot { color: var(--radar-amber-ink); }
.radar-chip[aria-pressed="true"] { background: rgba(59, 130, 246, 0.22); border-color: var(--radar-accent); color: var(--radar-on-pressed); }

.radar-locked { display: flex; flex-direction: column; gap: 10px; padding: 16px 18px; border-radius: 12px; border: 1px solid rgba(255, 181, 71, 0.5); background: linear-gradient(135deg, rgba(255, 181, 71, 0.1), rgba(59, 130, 246, 0.05)); }
.radar-locked-meta { display: flex; flex-wrap: wrap; align-items: center; gap: 10px; font-family: var(--radar-mono); font-size: 11px; letter-spacing: 2px; color: var(--radar-dim); }
.radar-locked-mark { color: var(--radar-amber-ink); }
.radar-locked-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 12px; padding-right: 36px; }
.radar-locked-title { font-size: 21px; font-weight: 600; line-height: 1.2; }
.radar-locked-kind { font-size: 14px; font-weight: 400; line-height: 1.4; color: var(--radar-muted); }
.radar-locked-facts { display: grid; grid-template-columns: 1fr 1fr; gap: 10px 18px; }
.radar-locked-fact-label { display: block; margin-bottom: 2px; font-family: var(--radar-mono); font-size: 10px; letter-spacing: 0.8px; color: var(--radar-dim); }
.radar-locked-fact-value { font-size: 15px; }
.radar-locked-detail { font-size: 14px; line-height: 1.4; color: var(--radar-muted); }
.radar-locked-actions { display: flex; align-items: center; gap: 8px; }
.radar-primary { min-height: 44px; padding: 10px 16px; border: 1px solid var(--radar-accent); border-radius: 8px; background: var(--radar-accent); color: #ffffff; font-size: 13px; font-weight: 700; letter-spacing: 1.5px; cursor: pointer; }
.radar-secondary { display: inline-flex; align-items: center; min-height: 44px; box-sizing: border-box; padding: 10px 16px; border: 1px solid rgba(59, 130, 246, 0.45); border-radius: 8px; color: var(--radar-ink); font-size: 13px; font-weight: 600; letter-spacing: 1.5px; text-decoration: none; }
button.radar-secondary { background: transparent; cursor: pointer; font-family: inherit; }
button.radar-secondary:disabled { opacity: 0.6; cursor: default; }
.radar-secondary:hover { background: rgba(59, 130, 246, 0.08); }
button.radar-secondary { background: none; font-family: inherit; cursor: pointer; }
button.radar-secondary:hover { background: rgba(59, 130, 246, 0.08); }

.radar-stale { margin: 0; padding: 8px 12px; border-radius: 8px; border: 1px solid var(--radar-amber); background: rgba(255, 181, 71, 0.1); color: var(--radar-stale-ink); font-size: 13px; }
.radar-empty { margin: 24px 0; color: var(--radar-muted); }
.radar-ack-error { color: var(--radar-amber-ink); font-size: 12px; }
.radar-unplaced { margin: 0; font: 12px var(--radar-mono); color: var(--radar-faint); }

.radar-list { display: flex; flex-direction: column; max-height: 540px; overflow-y: visible; padding-right: 4px; border-top: 1px solid var(--radar-line); }
.radar-list::-webkit-scrollbar { width: 8px; }
.radar-list::-webkit-scrollbar-thumb { background: rgba(59, 130, 246, 0.25); border-radius: 4px; }
.radar-row { display: grid; grid-template-columns: 56px auto minmax(0, 1fr) auto; gap: 12px; align-items: center; width: 100%; min-height: 54px; padding: 9px 10px 9px 12px; border: 0; border-bottom: 1px solid rgba(59, 130, 246, 0.08); border-left: 2px solid transparent; border-radius: 0; background: transparent; color: inherit; text-align: left; cursor: pointer; }
.radar-row--flight { grid-template-columns: 56px minmax(0, 1fr) auto; }
/* a document row has no tag column (it's never a task) and its "when" is a full date (2026-10-13), not a clock — the
   default 56px first column is sized for a short age like "4m", so it wraps a date onto three lines without this */
.radar-row--expiry { grid-template-columns: 92px minmax(0, 1fr) auto; box-sizing: border-box; text-align: left; cursor: pointer; }
.radar-doc-detail { display: grid; gap: 10px; margin: 0; }
.radar-doc-detail-row { display: grid; grid-template-columns: 130px minmax(0, 1fr); gap: 12px; align-items: baseline; }
.radar-doc-detail-row dd { margin: 0; overflow-wrap: anywhere; }
.radar-row:hover { background: rgba(59, 130, 246, 0.05); }
.radar-row.is-selected { border-left-color: var(--radar-amber); background: rgba(255, 181, 71, 0.08); }
.radar-row--resolved { opacity: 0.62; }
.radar-row-when { display: flex; flex-direction: column; gap: 2px; font-family: var(--radar-mono); }
.radar-row-age { font-size: 14px; font-weight: 600; color: var(--radar-ink); }
.radar-row-clock { font-size: 11px; color: var(--radar-dim); }
.radar-row-text { display: flex; flex-direction: column; gap: 3px; min-width: 0; }
.radar-row-title { font-size: 14px; font-weight: 600; color: var(--radar-ink-2); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.radar-row-detail { font-size: 12px; color: var(--radar-detail); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }

.radar-tag { min-width: 62px; box-sizing: border-box; padding: 3px 6px; border-radius: 4px; font-family: var(--radar-mono); font-size: 10px; font-weight: 600; letter-spacing: 1.5px; text-align: center; white-space: nowrap; }
.radar-tag--action { background: rgba(255, 181, 71, 0.16); border: 1px solid rgba(255, 181, 71, 0.6); color: var(--radar-amber); }
.radar-tag--open { background: rgba(59, 130, 246, 0.1); border: 1px solid rgba(59, 130, 246, 0.45); color: var(--radar-lime); }
.radar-tag--resolved { background: rgba(59, 130, 246, 0.08); border: 1px solid rgba(59, 130, 246, 0.3); color: var(--radar-accent); }

.radar-pill { padding: 3px 7px; border-radius: 4px; font-family: var(--radar-mono); font-size: 10px; font-weight: 600; letter-spacing: 1.5px; white-space: nowrap; }
.radar-pill--new, .radar-pill--uncrewed { background: var(--radar-accent); color: #ffffff; }
.radar-pill--cancelled, .radar-pill--critical, .radar-pill--missing { background: var(--radar-amber); color: #1f1300; }
.radar-pill--ack, .radar-pill--delayed, .radar-pill--warning, .radar-pill--late { border: 1px solid var(--radar-lime); color: var(--radar-pill-ack); }
.radar-pill--resolved, .radar-pill--manual { border: 1px solid rgba(59, 130, 246, 0.18); color: var(--radar-faint); }

/* The scope panel. */
.radar-panel { display: flex; flex-direction: column; gap: 12px; min-width: 0; }
/* One row, always: the heading never wraps into a second visible row, and the mode switch sits at its right, so a mode's
   longer note (bands vs ring) can neither change the row's height nor move the radar. The parts sit in the order they are
   given up when the row is short (title, range, on-scope chip, sweep, note): whatever does not fit wraps below the row and
   is clipped, so a part shows whole or not at all, in any language, and the note is cut with an ellipsis before it is
   dropped. The whole text is the heading's hover. */
.radar-toolbar { --radar-heading-h: 38px; display: flex; align-items: center; gap: 14px; font-family: var(--radar-mono); font-size: 12px; letter-spacing: 1.5px; color: var(--radar-dim); }
.radar-toolbar-info { flex: 1 1 auto; min-width: 0; display: flex; flex-wrap: wrap; align-content: flex-start; align-items: center; column-gap: 14px; row-gap: 14px; height: var(--radar-heading-h); overflow: hidden; white-space: nowrap; }
.radar-toolbar-info::before { content: ""; order: -1; flex: 0 0 0; height: var(--radar-heading-h); margin-right: -14px; }
.radar-toolbar-info > * { flex-shrink: 0; }
.radar-toolbar-info > .radar-toolbar-note { flex: 1 1 12ch; min-width: 0; max-width: max-content; overflow: hidden; text-overflow: ellipsis; }
.radar-toolbar .radar-modes { flex-shrink: 0; margin-left: auto; }
.radar-toolbar-title { font-family: var(--radar-display); font-size: 15px; font-weight: 600; letter-spacing: 3px; color: var(--radar-ink); }
.radar-toolbar-sweep { display: flex; align-items: center; gap: 6px; }
.radar-toolbar-only { padding: 2px 8px; border: 1px solid rgba(255, 181, 71, 0.45); border-radius: 4px; color: var(--radar-amber-ink); }
.radar-toolbar-sweep .radar-live-dot { width: 7px; height: 7px; animation: none; }
.radar-toolbar button { min-height: 40px; padding: 8px 14px; border: 1px solid rgba(59, 130, 246, 0.35); border-radius: 8px; background: transparent; color: var(--radar-muted); font-size: 12px; font-weight: 600; letter-spacing: 1.5px; cursor: pointer; }
.radar-toolbar button[aria-pressed="true"] { background: rgba(59, 130, 246, 0.2); border-color: var(--radar-accent); color: var(--radar-on-pressed); }

/* The scope is the largest square, at most 800px, that fits the box it is given; the box takes the panel's height left
   between the heading and the telemetry strip (see "The Radar fits its window" below), so the strip is never pushed
   below the fold and nothing here depends on a guess at the other rows' heights. */
.radar-scope-fit { flex: 1 1 0; min-height: 240px; container-type: size; }
.radar-scope { position: relative; width: min(100cqw, 100cqh, 800px); aspect-ratio: 1 / 1; margin: 0 auto; container-type: inline-size; }
.radar-disc { position: absolute; inset: 8%; border-radius: 50%; background: var(--radar-disc); box-shadow: 0 0 60px rgba(59, 130, 246, 0.18), inset 0 0 80px rgba(0, 0, 0, 0.35); }
.radar-svg { position: absolute; inset: 0; width: 100%; height: 100%; }
.radar-ring { fill: none; stroke: rgba(59, 130, 246, 0.2); stroke-width: 1.4; }
.radar-ring--rim { stroke: rgba(59, 130, 246, 0.55); stroke-width: 2; }
.radar-ring--now { fill: rgba(59, 130, 246, 0.07); stroke: rgba(59, 130, 246, 0.45); stroke-width: 1.6; animation: radar-now 2.4s ease-in-out infinite; }
.radar-spoke { stroke: rgba(59, 130, 246, 0.16); stroke-width: 1.2; stroke-dasharray: 3 7; }
.radar-sector-edge { stroke: rgba(59, 130, 246, 0.2); stroke-width: 1.2; }
.radar-ticks { stroke: rgba(59, 130, 246, 0.35); stroke-width: 1.4; }
.radar-ring--core { fill: rgba(255, 176, 32, 0.08); stroke: rgba(255, 176, 32, 0.55); stroke-width: 1.6; stroke-dasharray: 6 5; }
.radar-ring-label { fill: var(--radar-ring-label); font: 500 14px var(--radar-mono); letter-spacing: 1px; }
.radar-wedge { fill: rgba(59, 130, 246, 0.08); stroke: rgba(59, 130, 246, 0.35); stroke-width: 1; }
.radar-lockline { stroke: var(--radar-amber); stroke-width: 1.6; stroke-dasharray: 6 6; animation: radar-dash 1s linear infinite; }

.radar-centre, .radar-centre-ping { position: absolute; left: 50%; top: 50%; box-sizing: border-box; width: 14px; height: 14px; margin: -7px 0 0 -7px; border-radius: 50%; }
.radar-centre { background: #bfdbfe; box-shadow: 0 0 18px var(--radar-accent); }
.radar-centre-ping { border: 1.5px solid var(--radar-accent); animation: radar-ping 3s ease-out infinite; }

.radar-sweep {
  position: absolute; inset: 8%; border-radius: 50%; pointer-events: none; mix-blend-mode: var(--radar-sweep-blend);
  background: conic-gradient(from 0deg, rgba(59, 130, 246, 0) 0deg, rgba(59, 130, 246, 0) 250deg, rgba(59, 130, 246, 0.05) 300deg, rgba(59, 130, 246, 0.16) 335deg, rgba(59, 130, 246, 0.42) 357deg, rgba(191, 219, 254, 0.95) 359.4deg, rgba(59, 130, 246, 0) 360deg);
  animation-name: radar-sweep; animation-timing-function: linear; animation-iteration-count: infinite;
}

.radar-blip { position: absolute; width: 30px; height: 30px; margin: -15px 0 0 -15px; padding: 0; border: 0; background: transparent; display: flex; align-items: center; justify-content: center; cursor: pointer; }
.radar-blip--action { color: var(--radar-amber); }
.radar-blip--open { color: var(--radar-lime); }
.radar-blip--resolved { color: var(--radar-resolved); }
.radar-blip-dot { width: 13px; height: 13px; border-radius: 50%; background: currentColor; box-shadow: none; animation-name: radar-glow; animation-timing-function: linear; animation-iteration-count: infinite; }
.radar-blip--open .radar-blip-dot { width: 11px; height: 11px; }
.radar-blip--resolved .radar-blip-dot { width: 9px; height: 9px; }
.radar-reticle { position: absolute; width: 30px; height: 30px; margin: -15px 0 0 -15px; pointer-events: none; }
.radar-reticle svg { width: 30px; height: 30px; fill: none; stroke: var(--radar-amber); stroke-width: 3.5; filter: drop-shadow(0 0 4px rgba(255, 181, 71, 0.6)); animation: radar-spin 6s linear infinite; }

/* labels scale with the scope (container units), so a small scope never piles them onto the rings */
.radar-axis { position: absolute; transform: translate(-50%, -50%); padding: 0.35em 0.7em; border-radius: 6px; border: 1px solid transparent; background: var(--radar-axis-bg); color: var(--radar-dim); font-family: var(--radar-display); font-size: clamp(9px, 1.55cqi, 12px); font-weight: 600; letter-spacing: 0.12em; line-height: 1.2; text-transform: uppercase; text-align: center; white-space: nowrap; cursor: pointer; }
.radar-axis:hover { border-color: var(--radar-line); color: var(--radar-muted); }
.radar-axis--hot { color: var(--radar-amber-ink); }
.radar-axis[aria-pressed="true"] { background: rgba(59, 130, 246, 0.18); border-color: var(--radar-accent); color: var(--radar-ink); }
.radar-axis-count { display: block; margin-top: 2px; font-family: var(--radar-mono); font-size: 0.85em; font-weight: 500; letter-spacing: 0.08em; color: var(--radar-faint); }
.radar-axis--hot .radar-axis-count { color: var(--radar-amber); }

.radar-telemetry { display: flex; flex-direction: column; gap: 8px; padding: 12px 16px 10px; border-radius: 10px; border: 1px solid rgba(59, 130, 246, 0.14); background: var(--radar-telemetry-bg); }
.radar-scrub { width: 100%; margin: 0; accent-color: var(--radar-amber); }
.radar-arrivals { display: flex; flex-direction: column; gap: 6px; min-width: 0; }
.radar-arrivals-title { font-family: var(--radar-mono); font-size: 10px; letter-spacing: 2px; color: var(--radar-dim); }
.radar-arrivals svg { display: block; width: 100%; height: 40px; }
.radar-bar { fill: rgba(59, 130, 246, 0.75); }
.radar-bar--action { fill: var(--radar-amber); }
.radar-bar--empty { fill: rgba(59, 130, 246, 0.2); }
.radar-arrivals-axis { display: flex; justify-content: flex-end; font-family: var(--radar-mono); font-size: 10px; letter-spacing: 1.5px; color: var(--radar-faint); }
.radar-telemetry-read { padding-top: 8px; border-top: 1px solid rgba(59, 130, 246, 0.08); font-family: var(--radar-mono); font-size: 10.5px; letter-spacing: 1.5px; color: var(--radar-faint); }

/* The CRT: scanlines and a vignette over everything, never in the way of a click. Softened / off in light. */
.radar-crt {
  position: absolute; inset: 0; pointer-events: none;
  background: var(--radar-crt);
}

@keyframes radar-sweep { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }
/* the dot brightens as the beam passes (0%), then fades until the next turn. No halo: a shadow outside the dot stacks into a wash when many sit together. */
@keyframes radar-glow { 0%, 8% { opacity: 1; } 100% { opacity: 0.4; } }
@keyframes radar-ping { 0% { transform: scale(0.2); opacity: 0.8; } 100% { transform: scale(9); opacity: 0; } }
@keyframes radar-now { 0%, 100% { fill-opacity: 0.55; } 50% { fill-opacity: 1; } }
@keyframes radar-livedot { 0%, 100% { opacity: 1; } 50% { opacity: 0.25; } }
@keyframes radar-scroll { from { transform: translateX(0); } to { transform: translateX(-50%); } }
@keyframes radar-dash { to { stroke-dashoffset: -12; } }
@keyframes radar-spin { to { transform: rotate(360deg); } }
@keyframes radar-flicker { 0%, 100% { opacity: 0.97; } 47% { opacity: 0.93; } 50% { opacity: 0.99; } 53% { opacity: 0.94; } }

/* Light theme — same layout; paper grounds, darker ink, no CRT/flicker. Driven by the ops header toggle (html[data-theme]). */
html[data-theme="light"] .radar-screen {
  --radar-ink: #0f172a;
  --radar-ink-2: #020617;
  --radar-muted: #334155;
  --radar-dim: #475569;
  --radar-faint: #64748b;
  --radar-accent: #2563eb;
  --radar-amber: #b45309;
  --radar-amber-ink: #92400e;
  --radar-lime: #1d4ed8;
  --radar-resolved: #475569;
  --radar-line: rgba(37, 99, 235, 0.18);
  --radar-detail: #1d4ed8;
  --radar-stale-ink: #92400e;
  --radar-on-pressed: #1e3a8a;
  --radar-pill-ack: #1e40af;
  --radar-ring-label: rgba(37, 99, 235, 0.7);
  --radar-ground: #f8fafc;
  --radar-head-bg: #ffffff;
  --radar-panel-bg: #ffffff;
  --radar-panel-hover: #f1f5f9;
  --radar-disc: radial-gradient(circle, rgba(191, 219, 254, 0.85) 0%, rgba(226, 232, 240, 0.95) 55%, rgba(241, 245, 249, 1) 100%);
  --radar-axis-bg: #ffffff;
  --radar-telemetry-bg: #ffffff;
  --radar-crt: none;
  --radar-sweep-blend: multiply;
  animation: none;
}
html[data-theme="light"] .radar-disc { box-shadow: 0 0 40px rgba(37, 99, 235, 0.12), inset 0 0 40px rgba(148, 163, 184, 0.25); }
html[data-theme="light"] .radar-centre { background: #2563eb; }
html[data-theme="light"] .radar-primary { color: #ffffff; }
html[data-theme="light"] .radar-pill--new, html[data-theme="light"] .radar-pill--uncrewed { color: #ffffff; }
html[data-theme="light"] .radar-pill--cancelled, html[data-theme="light"] .radar-pill--critical, html[data-theme="light"] .radar-pill--missing { color: #ffffff; }
html[data-theme="light"] .radar-kpi[aria-pressed="true"] { background: rgba(37, 99, 235, 0.1); }
html[data-theme="light"] .radar-modes .radar-mode[aria-pressed="true"],
html[data-theme="light"] .radar-day-live { background: rgba(37, 99, 235, 0.12); }
html[data-theme="light"] .radar-chip[aria-pressed="true"],
html[data-theme="light"] .radar-toolbar button[aria-pressed="true"] { background: rgba(37, 99, 235, 0.14); color: var(--radar-on-pressed); }
html[data-theme="light"] .radar-row:hover { background: rgba(37, 99, 235, 0.06); }
html[data-theme="light"] .radar-row.is-selected { background: rgba(180, 83, 9, 0.08); }
html[data-theme="light"] .radar-filterbar { background: rgba(37, 99, 235, 0.08); }
html[data-theme="light"] .radar-locked { background: linear-gradient(135deg, rgba(180, 83, 9, 0.08), rgba(37, 99, 235, 0.06)); }
html[data-theme="light"] .radar-stale,
html[data-theme="light"] .radar-feed-pill--replay { background: rgba(180, 83, 9, 0.1); }

@media (prefers-reduced-motion: reduce) {
  .radar-screen, .radar-sweep, .radar-blip-dot, .radar-centre-ping, .radar-reticle svg, .radar-ring--now,
  .radar-lockline, .radar-live-dot { animation: none; }
}

/* The Radar fits its window. Beside the feed (wider than 1040px) the screen takes exactly the window's height under the
   console header, in the page or full screen; the feed's list scrolls inside its column and the scope shrinks to the
   space left, so the telemetry strip always stays in view. Stacked (narrower), the page scrolls as before. */
@media (min-width: 1041px) {
  .ops-app:has(> .radar-screen) { height: 100dvh; }
  .radar-screen { overflow-x: hidden; overflow-y: auto; }
  .radar-main { grid-template-rows: minmax(0, 1fr); }
  .radar-feed, .radar-panel { min-height: 0; }
  /* When the feed's fixed rows (tiles, chips, a selected item's banner) and the list's floor are taller than the window
     leaves it, the feed column scrolls inside itself; the whole screen, the radar with it, stays where it is. */
  .radar-feed { overflow-y: auto; scrollbar-width: thin; scrollbar-color: rgba(59, 130, 246, 0.25) transparent; }
  .radar-list { flex: 1 1 0; min-height: 120px; max-height: none; }
}
@media (max-width: 1040px) {
  .radar-scope-fit { flex: none; min-height: 0; container-type: inline-size; }
  .radar-scope { width: min(100cqw, 800px); }
}

/* a pending action: the label changes and a spinner runs, so a slow call never looks like a dead button */
.radar-busy { position: relative; padding-left: 38px; cursor: progress; opacity: 0.85; }
.radar-busy::before { content: ""; position: absolute; left: 14px; top: 50%; width: 14px; height: 14px; margin-top: -7px; border: 2px solid currentColor; border-right-color: transparent; border-radius: 50%; animation: radar-spin 0.8s linear infinite; }
@keyframes radar-spin { to { transform: rotate(360deg); } }
@media (prefers-reduced-motion: reduce) { .radar-busy::before { animation-duration: 2.4s; } }

/* Operations Control Panel (knowledge-base/features/ops-control-panel.md §5). Design tokens come from tokens.css. */
.ops-app { min-height: 100vh; display: flex; flex-direction: column; }
/* The panel's plain controls in the Radar's outlined style. Each selector is wholly inside :where() so it weighs
   nothing: an attribute or :hover left outside would outrank a screen's own class (it boxed the radar's blips). */
:where(.ops-app :is(button, select, input[type="datetime-local"])) { padding: 6px 12px; border: 1px solid var(--border-secondary); border-radius: 6px; background: transparent; color: var(--text-secondary); font: inherit; font-size: 13px; line-height: 1.25; cursor: pointer; }
:where(.ops-app button:hover:not(:disabled)) { border-color: var(--accent-primary); color: var(--text-primary); }
:where(.ops-app button[aria-pressed="true"]) { background: var(--accent-primary-light); border-color: var(--accent-primary); color: var(--text-primary); }
:where(.ops-app button:disabled) { opacity: 0.45; cursor: default; }
:where(.ops-app select option) { background: var(--bg-secondary); color: var(--text-primary); }
/* Segmented controls: one outer border; square seams (global button radius must not show through). */
.ops-view, .ops-timeline-rule, .ops-lang {
  display: inline-flex; align-items: stretch; border: 1px solid var(--border-secondary); border-radius: 8px; overflow: hidden; background: var(--surface-card);
}
.ops-view > button, .ops-timeline-rule > button, .ops-lang > button {
  margin: 0; border: 0; border-radius: 0; border-right: 1px solid var(--border-secondary); background: transparent; color: var(--text-secondary); min-height: 32px; padding: 6px 12px; line-height: 1.25;
}
.ops-view > button:last-child, .ops-timeline-rule > button:last-child, .ops-lang > button:last-child { border-right: 0; }
.ops-view > button:hover:not(:disabled), .ops-timeline-rule > button:hover:not(:disabled), .ops-lang > button:hover:not(:disabled) {
  border-color: var(--border-secondary); color: var(--text-primary); background: var(--surface-hover);
}
.ops-view > button[aria-pressed="true"], .ops-timeline-rule > button[aria-pressed="true"], .ops-lang > button[aria-pressed="true"] {
  background: var(--accent-primary-light); border-color: var(--border-secondary); color: var(--text-primary); font-weight: 700;
}
.ops-header { display: flex; align-items: center; gap: 24px; padding: 8px 16px; border-bottom: 1px solid var(--border-primary); }
.ops-brand { display: flex; align-items: center; gap: 10px; font-weight: 600; white-space: nowrap; }
.ops-logo { height: 30px; width: auto; display: block; }
.ops-tenant-logo { height: 28px; width: 28px; border-radius: 8px; object-fit: cover; display: block; }
.ops-menu { display: flex; gap: 2px; }
.ops-menu a { padding: 6px 12px; border-radius: 6px; color: inherit; text-decoration: none; }
.ops-menu a[aria-current="page"] { background: var(--accent-primary-light); color: var(--text-primary); box-shadow: inset 0 -2px 0 var(--accent-primary); font-weight: 600; }
.ops-operations { padding: 12px 16px; display: flex; flex-direction: column; gap: 12px; }
.ops-clocks { display: flex; flex-wrap: wrap; gap: 12px; }
.ops-clock { display: inline-flex; align-items: baseline; gap: 10px; padding: 8px 16px; border: 1px solid var(--border-primary); border-radius: 8px; background: var(--surface-card); }
.ops-clock-label { font: 600 12px var(--font-mono); letter-spacing: 0.06em; text-transform: uppercase; color: var(--text-tertiary); }
.ops-clock-time { font: 700 22px var(--font-mono); color: var(--text-primary); }
.ops-timeline { display: flex; flex-direction: column; gap: 4px; padding: 10px 14px 18px; border: 1px solid var(--border-primary); border-radius: 8px; background: var(--surface-card); color: var(--text-secondary); }
.ops-timeline-head { display: flex; flex-wrap: wrap; align-items: center; gap: 10px; margin-bottom: 6px; }
.ops-timeline-summary { font: 600 14px var(--font-mono); color: var(--text-primary); margin-right: auto; }
.ops-timeline-chips, .ops-timeline-anchor { display: inline-flex; gap: 6px; align-items: center; }
.ops-timeline-chips > button, .ops-timeline-anchor > button { min-height: 32px; }
.ops-timeline-density { display: block; width: 100%; height: 28px; }
.ops-timeline-bar { fill: var(--border-secondary); }
.ops-timeline-bar.on { fill: var(--accent-primary); }
.ops-timeline-track { position: relative; height: 24px; cursor: pointer; touch-action: none; user-select: none; }
.ops-timeline-rail { position: absolute; left: 0; right: 0; top: 10px; height: 4px; border-radius: 2px; background: var(--bg-tertiary); }
.ops-timeline-band { position: absolute; top: 8px; height: 8px; border-radius: 4px; background: color-mix(in srgb, var(--accent-primary) 55%, transparent); cursor: grab; }
.ops-timeline-band:active { cursor: grabbing; }
.ops-timeline-now { position: absolute; top: 0; width: 2px; height: 24px; margin-left: -1px; background: var(--accent-warning); pointer-events: none; }
.ops-timeline-handle { position: absolute; top: 2px; width: 14px; height: 20px; margin-left: -7px; border: 2px solid var(--surface-card); border-radius: 4px; background: var(--text-primary); cursor: ew-resize; }
.ops-timeline-handle:focus-visible { outline: 2px solid var(--accent-primary); outline-offset: 2px; }
.ops-timeline-ticks { position: relative; height: 14px; }
.ops-timeline-tick { position: absolute; transform: translateX(-50%); font: 10px var(--font-mono); color: var(--text-tertiary); }
.ops-timeline-tick:nth-child(odd) { visibility: hidden; }
@media (min-width: 1200px) { .ops-timeline-tick:nth-child(odd) { visibility: visible; } }
.ops-controls { display: flex; flex-wrap: wrap; align-items: center; gap: 12px; }
.ops-presets button[aria-pressed="true"] { font-weight: 700; }
.ops-show { margin-left: auto; display: inline-flex; flex-wrap: wrap; gap: 8px; align-items: center; }
.ops-show-chip { min-height: 32px; padding: 6px 12px; font: 600 12px var(--font-mono); letter-spacing: 0.02em; border-radius: 8px; }
.ops-show-chip--uncrewed { border-color: #f87171; color: #f87171; }
.ops-show-chip--uncrewed[aria-pressed="true"] { background: color-mix(in srgb, #f87171 22%, transparent); border-color: #f87171; color: #fecaca; }
.ops-show-chip--delayed { border-color: #ffb547; color: #ffb547; }
.ops-show-chip--delayed[aria-pressed="true"] { background: color-mix(in srgb, #ffb547 22%, transparent); border-color: #ffb547; color: #ffd89a; }
.ops-show-chip--cancelled { border-color: #f472b6; color: #f472b6; }
.ops-show-chip--cancelled[aria-pressed="true"] { background: color-mix(in srgb, #f472b6 22%, transparent); border-color: #f472b6; color: #fbcfe8; }
html[data-theme="light"] .ops-show-chip--uncrewed[aria-pressed="true"] { color: #b91c1c; background: color-mix(in srgb, #f87171 14%, transparent); }
html[data-theme="light"] .ops-show-chip--delayed[aria-pressed="true"] { color: #92400e; background: color-mix(in srgb, #ffb547 16%, transparent); }
html[data-theme="light"] .ops-show-chip--cancelled[aria-pressed="true"] { color: #9d174d; background: color-mix(in srgb, #f472b6 14%, transparent); }
.ops-show-clear { min-height: 32px; font-size: 12px; }

.ops-placeholder { padding: 24px 16px; }

/* Map | Table | Both — side by side on wide screens, stacked below 1200px. */
.ops-grid { display: flex; flex-direction: column; gap: 12px; }
.ops-grid--both { display: grid; grid-template-columns: minmax(0, 3fr) minmax(0, 2fr); gap: 12px; align-items: start; }
@media (max-width: 1200px) { .ops-grid--both { grid-template-columns: minmax(0, 1fr); } }
.ops-table { overflow-x: auto; }
.ops-time { white-space: nowrap; }

/* The SVG map, after the dcortex-gen2 ops map: a fixed dark field in both themes, in the Radar's green-black.
   Stroke widths and sizes are set per element in screen pixels; the colours live here. */
.ops-map { position: relative; display: block; border: 1px solid #1e2a40; border-radius: 8px; overflow: hidden; background: #0a0f1a; }
.ops-map-head { display: flex; justify-content: space-between; gap: 12px; padding: 6px 12px; font: 600 11px var(--font-mono); letter-spacing: 0.04em; color: #8494ac; text-transform: uppercase; border-bottom: 1px solid #1e2a40; }
.ops-map-asof { color: #5a6a85; text-transform: none; }
.ops-map-svg { display: block; width: 100%; height: 62vh; min-height: 360px; background: #0a0f1a; cursor: grab; touch-action: none; }
.ops-map-svg:active { cursor: grabbing; }
.ops-map-controls { position: absolute; top: 36px; right: 8px; display: flex; gap: 4px; z-index: 1; }
.ops-map-controls button { border-color: #2a3a58; background: #0a0f1a; color: #8494ac; }
.ops-map-controls button:hover { border-color: #3b82f6; color: #e6edf7; }
.ops-map-credit { position: absolute; right: 8px; bottom: 34px; font: 9px var(--font-mono); letter-spacing: 0.06em; color: #5a6a85; opacity: 0.7; pointer-events: none; }
.ops-graticule { fill: none; stroke: #1e2a40; }
.ops-land { fill: #16233a; stroke: #2a3a58; }
.ops-borders { fill: none; stroke: #2a3a58; opacity: 0.7; }
.ops-station-dot { fill: #5a6a85; opacity: 0.55; }
.ops-path { fill: none; stroke: #8494ac; stroke-linecap: round; opacity: 0.22; cursor: pointer; }
.ops-path--departed, .ops-path--airborne { stroke: #34d399; }
.ops-path--landed { stroke: #5a6a85; }
.ops-path--quiet { opacity: 0.22; }
.ops-path--diverted { stroke: #b99cf0; opacity: 1; }
.ops-path--delayed { stroke: #ffb547; opacity: 1; }
.ops-path--cancelled { stroke: #f472b6; opacity: 0.85; }
.ops-path--short { stroke: #f87171; opacity: 1; }
.ops-route:hover .ops-path { opacity: 1; }
.ops-flight-hit { fill: none; stroke: transparent; pointer-events: stroke; cursor: pointer; }
.ops-halo { fill: none; stroke: #8494ac; opacity: 0.5; }
.ops-origin-mark { fill: #8494ac; }
.ops-airport--base .ops-halo { stroke: #34d399; opacity: 0.8; }
.ops-airport--base .ops-origin-mark { fill: #34d399; }
.ops-dest-mark { fill: #8494ac; }
.ops-event { cursor: pointer; }
.ops-event--delay circle { fill: #ffb547; }
.ops-event--delay text { fill: #ffb547; font-family: var(--font-mono); font-weight: 600; paint-order: stroke; stroke: #0a0f1a; stroke-linejoin: round; }
.ops-event--cancelled path { stroke: #f472b6; stroke-linecap: round; }
.ops-event--recovering circle { fill: #34d399; }
.ops-event--recovering text { fill: #34d399; }
.ops-event--diversion path { fill: #0a0f1a; stroke: #b99cf0; }
.ops-event--alert path { fill: #e8c547; stroke: #0a0f1a; }
.ops-event--alert text { fill: #0a0f1a; font-family: var(--font-mono); font-weight: 700; }
.ops-event--short rect { fill: #f87171; stroke: #0a0f1a; }
.ops-event--short text { fill: #0a0f1a; font-family: var(--font-mono); font-weight: 700; }
.ops-crew-icon { fill: #0a0f1a; }
.ops-legend-crew { width: 12px; height: 12px; margin: 0 4px 0 0; vertical-align: middle; overflow: visible; }
.ops-legend-crew .ops-crew-icon { fill: #f87171; }
.ops-station-tasks rect { fill: #e6edf7; stroke: #0a0f1a; }
.ops-station-tasks text { fill: #0a0f1a; font-family: var(--font-mono); font-weight: 700; }
.ops-position circle { fill: #34d399; stroke: #0a0f1a; cursor: pointer; }
.ops-label { font-family: var(--font-mono); letter-spacing: 0.02em; fill: #8494ac; paint-order: stroke; stroke: #0a0f1a; stroke-linejoin: round; pointer-events: none; }
.ops-label--strong { fill: #e6edf7; font-weight: 600; }
.ops-legend { display: flex; flex-wrap: wrap; align-items: center; gap: 10px 16px; margin: 0; padding: 8px 12px; font-size: 12px; color: #8494ac; border-top: 1px solid #1e2a40; }
.ops-legend-title { font: 700 10px var(--font-mono); letter-spacing: 0.06em; text-transform: uppercase; color: #5a6a85; }
.ops-legend-group { display: flex; flex-wrap: wrap; gap: 12px; margin: 0; padding: 0; list-style: none; }
.ops-legend-group--quiet { opacity: 0.55; }
.ops-legend li::before { content: ""; display: inline-block; width: 14px; height: 3px; margin-right: 6px; vertical-align: middle; background: #8494ac; }
.ops-legend--short::before { background: repeating-linear-gradient(90deg, #f87171 0 2px, transparent 2px 5px) !important; }
.ops-legend--delayed::before { background: #ffb547 !important; }
.ops-legend--cancelled::before { background: repeating-linear-gradient(90deg, #f472b6 0 3px, transparent 3px 5px) !important; }
.ops-legend--diverted::before { background: #b99cf0 !important; }
.ops-legend--alert::before { width: 0 !important; height: 0 !important; background: none !important; border-left: 5px solid transparent; border-right: 5px solid transparent; border-bottom: 9px solid #e8c547; }
.ops-legend--other::before { opacity: 0.5; }
.ops-theme { margin-left: auto; min-width: 36px; padding: 6px 10px; border-radius: 6px; font-size: 16px; line-height: 1; }

/* The flight modal (§5d/§5c-3): a status strip, the two ends as cards, then events and crew. */
.ops-detail { display: flex; flex-direction: column; gap: 18px; color: var(--text-primary); }
.ops-muted { color: var(--text-secondary); }
/* A rotating box's bounds grow by up to √2, and transformed boxes count as scrollable overflow: at the foot of a modal the
 * spinner's corners toggled the scrollbar twice a turn. Clipping the row keeps the round ink and drops the box corners. */
.ops-recheck-pending, .ops-loading-note { overflow: clip; }
.ops-recheck-pending { display: flex; align-items: flex-start; gap: 10px; }
.ops-spinner { flex: none; width: 14px; height: 14px; margin-top: 3px; border: 2px solid currentColor; border-right-color: transparent; border-radius: 50%; animation: ops-spin 0.8s linear infinite; }
@keyframes ops-spin { to { transform: rotate(360deg); } }
@media (prefers-reduced-motion: reduce) { .ops-spinner { animation-duration: 2.4s; } }
.ops-detail-strip { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; }
.ops-pill { display: inline-flex; align-items: center; padding: 3px 10px; border-radius: 999px; font-size: 12px; font-weight: 600; letter-spacing: 0.02em; background: var(--bg-tertiary); color: var(--text-secondary); }
.ops-pill--departed, .ops-pill--airborne, .ops-pill--crew-full, .ops-pill--ok { background: color-mix(in srgb, var(--accent-success) 18%, transparent); color: var(--accent-success); }
.ops-pill--landed { background: color-mix(in srgb, var(--text-tertiary) 20%, transparent); color: var(--text-secondary); }
.ops-pill--cancelled, .ops-pill--crew-short { background: color-mix(in srgb, var(--accent-error) 18%, transparent); color: var(--accent-error); }
.ops-pill--diverted { background: rgba(185, 156, 240, 0.2); color: #b99cf0; }
.ops-pill--late { background: color-mix(in srgb, var(--accent-warning) 18%, transparent); color: var(--accent-warning); }
.ops-pill--crew-unknown { background: color-mix(in srgb, var(--text-tertiary) 18%, transparent); color: var(--text-tertiary); }
.ops-chip { padding: 3px 8px; border: 1px solid var(--border-secondary); border-radius: 6px; font: 600 12px var(--font-mono); color: var(--text-secondary); }
.ops-legs { display: grid; grid-template-columns: 1fr auto 1fr; align-items: stretch; gap: 12px; }
.ops-legs-arrow { align-self: center; font-size: 22px; color: var(--text-tertiary); }
.ops-leg-card { display: flex; flex-direction: column; gap: 2px; padding: 14px 16px; border: 1px solid var(--border-primary); border-radius: 10px; background: var(--surface-card); }
.ops-leg-side { font: 600 11px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--text-tertiary); }
.ops-leg-code { font: 700 30px var(--font-mono); letter-spacing: 0.04em; color: var(--text-primary); }
.ops-leg-city { font-size: 13px; color: var(--text-secondary); }
.ops-leg-code[title], [data-testid="ops-place"][title] { cursor: help; }
.ops-leg-date { font-size: 12px; color: var(--text-tertiary); margin-bottom: 8px; }
.ops-leg-times { display: grid; grid-template-columns: max-content 1fr; gap: 4px 14px; margin: 0; font-size: 13px; }
.ops-leg-times dt { color: var(--text-tertiary); }
.ops-leg-times dd { margin: 0; font-family: var(--font-mono); color: var(--text-primary); }
.ops-progress { display: flex; flex-direction: column; gap: 6px; }
.ops-progress-track { height: 6px; border-radius: 3px; background: var(--bg-tertiary); overflow: hidden; }
.ops-progress-fill { height: 100%; background: var(--accent-success); }
.ops-detail-section { display: flex; flex-direction: column; gap: 10px; padding-top: 14px; border-top: 1px solid var(--border-primary); }
.ops-detail-section-head { display: flex; align-items: center; justify-content: space-between; gap: 12px; }
.ops-detail-section-head h3 { margin: 0; font: 600 11px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--text-tertiary); }
.ops-detail-section p { margin: 0; }
.ops-event-chips { display: flex; flex-wrap: wrap; gap: 6px; margin: 0; padding: 0; list-style: none; }
.ops-event-chip { padding: 4px 10px; border-radius: 6px; font-size: 13px; background: var(--bg-tertiary); color: var(--text-primary); border-left: 3px solid var(--text-tertiary); }
.ops-event-chip--delay { border-left-color: var(--accent-warning); }
.ops-event-chip--recovering { border-left-color: var(--accent-success); }
.ops-event-chip--alert { border-left-color: #e8c547; }
.ops-event-chip--diversion { border-left-color: #b99cf0; }
.ops-positions { display: flex; flex-wrap: wrap; gap: 8px; margin: 0; padding: 0; list-style: none; }
.ops-position { display: inline-flex; align-items: baseline; gap: 8px; padding: 6px 12px; border: 1px solid var(--border-primary); border-radius: 8px; background: var(--surface-card); }
.ops-position-code { font: 600 12px var(--font-mono); color: var(--text-tertiary); }
.ops-position-count { font: 700 16px var(--font-mono); color: var(--accent-success); }
.ops-position--short { border-color: color-mix(in srgb, var(--accent-error) 60%, transparent); }
.ops-position--short .ops-position-count { color: var(--accent-error); }
.ops-position-deadhead { font: 600 12px var(--font-mono); color: var(--text-tertiary); }
.ops-crew-list { display: grid; grid-template-columns: repeat(auto-fill, minmax(min(100%, 300px), 1fr)); gap: 6px; margin: 0; padding: 0; list-style: none; }
.ops-crew-row { display: flex; flex-wrap: wrap; align-items: center; gap: 6px 10px; padding: 6px 10px; border-radius: 8px; background: var(--surface-card); min-width: 0; }
.ops-crew-pos { min-width: 30px; padding: 2px 6px; border-radius: 4px; background: var(--bg-tertiary); text-align: center; font: 700 11px var(--font-mono); color: var(--text-secondary); }
.ops-crew-name { flex: 1 1 110px; min-width: 0; font-size: 13px; color: var(--text-primary); overflow-wrap: anywhere; }
.ops-crew-row .ops-pill { flex: none; white-space: nowrap; }
.ops-crew-row--deadhead { opacity: 0.75; }
/* the delay re-check: one crew member per row — position, name, verdict, then the rules it names on their own line */
.ops-crew-list--recheck { grid-template-columns: 1fr; }
.ops-crew-list--recheck .ops-crew-row { flex-wrap: wrap; }
.ops-crew-list--recheck .ops-crew-name { flex: 1 1 auto; min-width: 0; }
.ops-crew-list--recheck .ops-pill { white-space: nowrap; flex: none; }
.ops-crew-list--recheck .ops-recheck-rules { flex: 1 0 100%; padding-left: 40px; font-size: 12px; line-height: 1.4; }
/* every hard rule the engine ran, folded under the crew row */
.ops-crew-list--recheck .ops-recheck-rulelist { flex: 1 0 100%; padding-left: 40px; font-size: 12px; line-height: 1.5; color: var(--text-secondary); }
.ops-recheck-rulelist summary { cursor: pointer; color: var(--text-secondary); }
.ops-recheck-rulelist ul { margin: 4px 0 0; padding: 0; list-style: none; }
.ops-recheck-rule--pass > span { color: var(--accent-success); }
.ops-recheck-rule--breach { color: var(--accent-error); }
.ops-recheck-rule--unjudged > span { color: var(--accent-warning); }
.ops-recheck-rule > .ops-recheck-measure { color: var(--text-secondary); }
.ops-pill--recheck-legal { background: color-mix(in srgb, var(--accent-success) 18%, transparent); color: var(--accent-success); }
.ops-pill--recheck-breach { background: color-mix(in srgb, var(--accent-error) 18%, transparent); color: var(--accent-error); }
.ops-pill--recheck-datacheck, .ops-pill--recheck-unchecked { background: color-mix(in srgb, var(--accent-warning) 18%, transparent); color: var(--accent-warning); }
.ops-crew-tag { margin-left: auto; font-size: 11px; color: var(--text-tertiary); }
.ops-rc-find { flex: none; margin-left: auto; white-space: nowrap; padding: 2px 8px; border: 1px solid var(--border-primary); border-radius: 6px; background: var(--bg-tertiary); font-size: 11px; color: var(--text-primary); cursor: pointer; }
.ops-rc-find[aria-pressed="true"] { border-color: var(--accent-error); }
[data-testid="ops-rc-swap"][aria-pressed="true"] { border-color: var(--accent-primary, var(--border-primary)); }
.ops-rc { flex: none; margin-top: 10px; padding: 12px; border: 1px solid var(--border-primary); border-radius: 10px; background: var(--surface-card); max-width: 100%; box-sizing: border-box; overflow: hidden; }
.ops-rc-head { display: flex; flex-wrap: wrap; align-items: baseline; gap: 10px; margin-bottom: 8px; }
.ops-rc-head h4 { margin: 0; font-size: 13px; }
.ops-rc-banner { margin: 0 0 8px; padding: 8px 10px; border-left: 3px solid var(--accent-info, var(--border-primary)); border-radius: 6px; background: var(--bg-tertiary); font-size: 12px; line-height: 1.45; color: var(--text-primary); }
.ops-rc-banner--warn { border-left-color: var(--accent-warning, var(--accent-error)); }
.ops-rc-excluded { margin: 0 0 8px; font-size: 11px; }
.ops-rc-group { margin: 0 0 8px; }
.ops-rc-group-head { cursor: pointer; margin: 0 0 6px; font: 600 12px var(--font-mono); color: var(--text-secondary); }
.ops-rc-group--legal > .ops-rc-group-head { color: var(--accent-success); }
.ops-rc-group--illegal > .ops-rc-group-head { color: var(--accent-error); }
.ops-rc-list { display: grid; gap: 8px; margin: 0; padding: 0; list-style: none; }
.ops-rc-candidate { padding: 10px 12px; border: 1px solid var(--border-primary); border-left-width: 3px; border-radius: 8px; background: var(--bg-tertiary); min-width: 0; }
.ops-rc-candidate--legal { border-left-color: var(--accent-success); }
.ops-rc-candidate--illegal { border-left-color: var(--accent-error); }
.ops-rc-candidate--not-evaluated { border-left-color: var(--accent-warning, var(--text-tertiary)); }
.ops-rc-candidate-head { display: flex; flex-wrap: wrap; align-items: center; gap: 10px; }
.ops-rc-rank { min-width: 18px; font: 700 12px var(--font-mono); color: var(--text-tertiary); text-align: right; }
.ops-rc-avatar { display: inline-grid; place-items: center; width: 30px; height: 30px; border-radius: 50%; background: var(--surface-card); border: 1px solid var(--border-primary); font: 700 11px var(--font-mono); color: var(--text-secondary); flex: none; }
.ops-rc-who { display: flex; flex-direction: column; min-width: 0; }
.ops-rc-name { font-size: 14px; font-weight: 600; color: var(--text-primary); overflow-wrap: anywhere; }
.ops-rc-meta { font: 11px var(--font-mono); overflow-wrap: anywhere; }
.ops-rc-id { font: 11px var(--font-mono); }
.ops-rc-positioning { font-size: 11px; color: var(--accent-warning, var(--text-secondary)); }
.ops-rc-verdict { font-weight: 600; }
.ops-rc-verdict--legal { color: var(--accent-success); }
.ops-rc-verdict--illegal { color: var(--accent-error); }
.ops-rc-verdict--not-evaluated { color: var(--accent-warning, var(--text-secondary)); }
.ops-rc-verdict--needs-data-check { color: var(--text-secondary); }
.ops-rc-datanotes { margin: 8px 0 0 28px; font-size: 12px; color: var(--text-secondary); }
.ops-rc-datanote--breach { color: var(--accent-warning, var(--accent-error)); font-weight: 600; }
.ops-rc-datanotes-head { margin: 0 0 3px; }
.ops-rc-datanotes ul { display: grid; gap: 2px; margin: 0; padding-left: 16px; overflow-wrap: anywhere; }
.ops-rc-expand { margin-left: auto; font-size: 11px; }
.ops-rc-blockers { display: grid; gap: 3px; margin: 8px 0 0 28px; padding: 0; list-style: none; font-size: 12px; line-height: 1.4; }
.ops-rc-blocker { padding-left: 14px; position: relative; color: var(--accent-error); overflow-wrap: anywhere; }
.ops-rc-blocker::before { content: "✕"; position: absolute; left: 0; font-size: 10px; }
.ops-rc-blocker--missing { color: var(--accent-warning, var(--accent-error)); }
.ops-rc-blocker--missing::before { content: "?"; font-weight: 700; }
.ops-rc-blocker--unchecked { color: var(--accent-warning, var(--accent-error)); }
.ops-rc-blocker--unchecked::before { content: "?"; font-weight: 700; }
.ops-rc-blocker--shared { color: var(--text-tertiary); }
.ops-rc-blocker--shared::before { content: ""; }
.ops-rc-note { margin: 6px 0 0 28px; font-size: 12px; }
.ops-rc-rules { width: 100%; table-layout: fixed; margin-top: 10px; border-collapse: collapse; font-size: 12px; }
.ops-rc-col-rule { width: 60%; }
.ops-rc-col-value { width: 24%; }
.ops-rc-col-margin { width: 16%; }
.ops-rc-rules th { text-align: left; font-weight: 600; color: var(--text-tertiary); }
.ops-rc-rules th, .ops-rc-rules td { padding: 4px 6px; border-top: 1px solid var(--border-primary); vertical-align: top; overflow-wrap: break-word; }
.ops-rc-rules td:nth-child(2), .ops-rc-rules td:nth-child(3) { font-family: var(--font-mono); overflow-wrap: normal; white-space: nowrap; }
.ops-rc-mark { display: inline-block; width: 16px; font-weight: 700; }
.ops-rc-rule--pass { color: var(--text-secondary); }
.ops-rc-rule--pass .ops-rc-mark { color: var(--accent-success); }
.ops-rc-rule--fail { color: var(--text-primary); }
.ops-rc-rule--fail .ops-rc-mark, .ops-rc-rule--fail td:nth-child(3) { color: var(--accent-error); }
@media (max-width: 640px) { .ops-legs { grid-template-columns: 1fr; } .ops-legs-arrow { display: none; } }

/* The rules browser (knowledge-base/decisions/control-tower-v3.md §16): the summary strip, tier chips, one table per
   tier, and the rule's detail as a side panel. */
.ops-rules { padding: 12px 16px; display: flex; flex-direction: column; gap: 12px; }
.ops-rules-summary { display: flex; flex-wrap: wrap; align-items: baseline; gap: 8px 18px; padding: 10px 14px; border: 1px solid var(--border-primary); border-radius: 8px; background: var(--surface-card); color: var(--text-secondary); }
.ops-rules-generation { font: 700 18px var(--font-mono); color: var(--text-primary); }
.ops-rules-hash, .ops-rules-code { font: 12px var(--font-mono); color: var(--text-tertiary); }
.ops-rules-controls { display: flex; flex-wrap: wrap; align-items: center; gap: 12px; }
.ops-rules-controls input[type="search"] { min-width: 260px; padding: 6px 10px; border-radius: 6px; border: 1px solid var(--border-secondary); background: var(--bg-secondary); color: inherit; }
.ops-rules-tiers { display: inline-flex; flex-wrap: wrap; gap: 6px; }
.ops-rules-tiers button { border-radius: 999px; padding: 4px 12px; border: 1px solid var(--border-secondary); background: transparent; color: inherit; cursor: pointer; }
.ops-rules-tiers button[aria-pressed="true"] { background: var(--bg-tertiary); font-weight: 700; }
.ops-rules-count { margin-left: 4px; padding: 0 6px; border-radius: 999px; background: var(--bg-secondary); font-size: 11px; }
.ops-rules-group { width: 100%; border-collapse: collapse; }
.ops-rules-group caption { text-align: left; padding: 8px 0 4px; font-weight: 700; letter-spacing: 0.04em; text-transform: uppercase; font-size: 12px; color: var(--text-tertiary); }
.ops-rules-group th, .ops-rules-group td { text-align: left; padding: 6px 8px; border-bottom: 1px solid var(--border-primary); vertical-align: top; }
.ops-rules-group tbody tr { cursor: pointer; }
.ops-rules-group tbody tr:hover, .ops-rules-group tbody tr:focus-visible { background: var(--surface-card); outline: none; }
.ops-rules-note { padding: 24px 16px; }
